begin;
-- Tests always roll back, including all synthetic responses and invitations.
insert into feedback_private.organizers(id,token_hash,label) values ('11111111-1111-4111-8111-111111111111',encode(extensions.digest('feedback-test-organizer','sha256'),'hex'),'Rollback-only organizer');
create function pg_temp.assert(p boolean, label text) returns void language plpgsql as $$ begin if p is distinct from true then raise exception 'Failed: %',label; end if; end $$;
do $$
declare qs jsonb; a jsonb := '{"enjoyment":5,"experiences":{"food":4,"dj":5,"karaoke":3,"dancing":"na","atmosphere":2},"connection":"somewhat","connection_help":"time","future":{"choices":["games","other"],"other":"Museum"}}';
begin
 select questions into qs from feedback_private.surveys where slug='rb-karaoke';
 perform pg_temp.assert(feedback_private.valid_questions(qs),'question schema');
 perform pg_temp.assert(feedback_private.valid_answers(qs,a),'valid response, optional text omitted');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,a-'enjoyment'),'missing required');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,jsonb_set(a,'{experiences,food}','null')),'matrix null');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,jsonb_set(a,'{experiences,food}','"5"')),'matrix string');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,jsonb_set(a,'{future,choices}','["games","music","other"]')),'too many choices');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,jsonb_set(a,'{future,choices}','["games","games"]')),'duplicate choices');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,a||'{"email":"test@example.com"}'),'unexpected identity field');
 perform pg_temp.assert(not feedback_private.valid_answers(qs,jsonb_set(a,'{future,other}','""')),'empty other');
end $$;
set local role anon;
select pg_temp.assert(public.rcap_feedback('get','{"slug":"rb-karaoke"}')->>'title'='Your night. Your honest take.','anonymous public read');
do $$
declare payload jsonb; got_error boolean:=false; s jsonb; out jsonb;
begin
 payload:='{"survey":"7cd40195-1428-45cd-8192-b56dd4ad9106","id":"22222222-2222-4222-8222-222222222222","answers":{"enjoyment":5,"experiences":{"food":4,"dj":5,"karaoke":3,"dancing":"na","atmosphere":2},"connection":"somewhat","connection_help":"time","future":{"choices":["games"]}}}';
 perform public.rcap_feedback('submit',payload);
 perform public.rcap_feedback('submit',payload);
 begin perform public.rcap_feedback('dashboard','{}'); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'anonymous dashboard denied');got_error:=false;
 begin perform public.rcap_feedback('results','{"survey":"7cd40195-1428-45cd-8192-b56dd4ad9106","token":"feedback-test-organizer"}'); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'organizer cannot read another event');got_error:=false;
 begin perform public.rcap_feedback('submit',jsonb_set(payload,'{answers,enjoyment}','null')); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'server rejects missing rating');got_error:=false;
 s:=public.rcap_feedback('get','{"slug":"rb-karaoke"}');
 s:=s||'{"id":"33333333-3333-4333-8333-333333333333","slug":"rollback-test-survey","status":"draft"}';
 perform public.rcap_feedback('save',jsonb_build_object('token','feedback-test-organizer','survey',s));
 perform pg_temp.assert(jsonb_array_length(public.rcap_feedback('dashboard','{"token":"feedback-test-organizer"}')->'surveys')=1,'organizer dashboard shows own event');
 perform pg_temp.assert(jsonb_array_length(public.rcap_feedback('results','{"token":"feedback-test-organizer","survey":"33333333-3333-4333-8333-333333333333"}')->'voices')=0,'own results query returns empty voices');
 s:=s||'{"status":"published"}';
 perform public.rcap_feedback('save',jsonb_build_object('token','feedback-test-organizer','survey',s));
 begin perform public.rcap_feedback('save',jsonb_build_object('token','feedback-test-organizer','survey',s)); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'published definitions frozen');got_error:=false;
 perform public.rcap_feedback('status','{"token":"feedback-test-organizer","survey":"33333333-3333-4333-8333-333333333333","status":"closed"}');
 begin perform public.rcap_feedback('get','{"slug":"rollback-test-survey"}'); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'closed survey hidden');got_error:=false;
 begin perform public.rcap_feedback('voice','{"survey":"7cd40195-1428-45cd-8192-b56dd4ad9106","id":"44444444-4444-4444-8444-444444444444","duration":31,"mime":"audio/webm","permission":"private"}'); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'voice duration capped');got_error:=false;
 begin perform public.rcap_feedback('voice','{"survey":"7cd40195-1428-45cd-8192-b56dd4ad9106","id":"44444444-4444-4444-8444-444444444444","duration":10,"mime":"audio/webm"}'); exception when others then got_error:=true; end;
 perform pg_temp.assert(got_error,'voice permission required');
 perform public.rcap_feedback('voice','{"survey":"7cd40195-1428-45cd-8192-b56dd4ad9106","id":"44444444-4444-4444-8444-444444444444","duration":10,"mime":"audio/webm","permission":"private"}');
 perform pg_temp.assert(not feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',true),'upload needs capability');
 perform set_config('request.headers','{"x-feedback-token":"44444444-4444-4444-8444-444444444444"}',true);
 perform pg_temp.assert(feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',true),'correct upload capability');
 perform pg_temp.assert(not feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',false),'uploader cannot read other stored voices');
end $$;
reset role;
select pg_temp.assert((select count(*)=1 from feedback_private.responses where id='22222222-2222-4222-8222-222222222222'),'idempotent submission');
update feedback_private.voices set complete=true,survey_id='33333333-3333-4333-8333-333333333333' where id='44444444-4444-4444-8444-444444444444';
select set_config('request.headers','{"x-feedback-admin":"feedback-test-organizer"}',true);
select pg_temp.assert(not feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',false),'private voice withheld from its event organizer');
update feedback_private.voices set permission='community' where id='44444444-4444-4444-8444-444444444444';
select pg_temp.assert(feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',false),'community voice accessible to its organizer');
select set_config('request.headers','{"x-feedback-admin":"wrong-token"}',true);
select pg_temp.assert(not feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',false),'wrong organizer cannot read voice');
update feedback_private.voices set permission='private' where id='44444444-4444-4444-8444-444444444444';
select set_config('request.headers',jsonb_build_object('x-feedback-admin',(select admin_pass from public.vault_settings where house='rcap'))::text,true) is not null as leadership_header_set;
select pg_temp.assert(feedback_private.voice_access('44444444-4444-4444-8444-444444444444/recording',false),'leadership can read private voice');
select pg_temp.assert(not has_table_privilege('anon','feedback_private.responses','select'),'anonymous cannot read response table');
select pg_temp.assert(not has_table_privilege('authenticated','feedback_private.responses','select'),'signed-in member cannot read response table');
update feedback_private.organizers set revoked=true where id='11111111-1111-4111-8111-111111111111';
set local role anon;
do $$ declare denied boolean:=false; begin begin perform public.rcap_feedback('dashboard','{"token":"feedback-test-organizer"}'); exception when others then denied:=true; end; perform pg_temp.assert(denied,'revoked invitation denied');end $$;
reset role;
select 'All feedback database checks passed; changes rolled back' as result;
rollback;
